import { useMemo, useRef, useState } from 'react';
import { SchemaForm } from '@schemastud/seam';
import { Card, CardContent, CardHeader, CardTitle } from '@schemastud/ui';
import { useIntakeSubmission } from './hooks';
import { useIntakeServices } from './provider';
import type {
    EntityIntakeFormSectionData,
    IntakeFields,
    IntakeFormRenderProps,
} from './types';

/** Mount with a new key when the selected entity or section changes. */
export function IntakeSectionForm({
    section,
    disabled = false,
}: {
    section: EntityIntakeFormSectionData;
    disabled?: boolean;
}) {
    const [fields, setFields] = useState<IntakeFields>(
        Array.isArray(section.fields) ? {} : section.fields,
    );
    const submit = useIntakeSubmission(section.key);
    const submitting = useRef(false);
    const { renderForm } = useIntakeServices();
    // The card header already names the section, so the default form drops the schema's root
    // title (RJSF would print it again as a legend: "Contact details" twice). Memoized: SchemaForm
    // re-resolves on every new schema identity.
    const formSchema = useMemo(() => {
        const { title: _rootTitle, ...untitled } = section.schema;
        return untitled;
    }, [section.schema]);
    const form: IntakeFormRenderProps = {
        schema: section.schema,
        formData: fields,
        disabled: disabled || submit.isPending,
        onChange: (next) => {
            if (submitting.current || submit.isPending) return;
            setFields(next);
            submit.reset();
        },
        onSubmit: (next) => {
            if (disabled || submitting.current || submit.isPending) return;
            submitting.current = true;
            submit.mutate(next, {
                onSettled: () => {
                    submitting.current = false;
                },
            });
        },
    };
    return (
        <Card aria-busy={submit.isPending || undefined}>
            <CardHeader>
                <CardTitle>
                    {String(section.schema.title ?? section.key)}
                </CardTitle>
            </CardHeader>
            <CardContent>
                {renderForm ? (
                    renderForm(form)
                ) : (
                    <SchemaForm
                        schema={formSchema}
                        // RJSF's form stacks the fields and the Submit row with no gap of its own.
                        className="rjsf grid gap-4"
                        formData={form.formData}
                        disabled={form.disabled}
                        onChange={({ formData }) =>
                            form.onChange(formData ?? {})
                        }
                        onSubmit={({ formData }) =>
                            form.onSubmit(formData ?? {})
                        }
                    />
                )}
                {/* Status lines sit in the form's text size, not the 16px body default. */}
                {submit.isPending && (
                    <p role="status" className="mt-3 text-sm text-muted-foreground">
                        Submitting section…
                    </p>
                )}
                {submit.isError && (
                    <p role="alert" className="mt-3 text-sm text-destructive">
                        {submit.error instanceof Error && submit.error.message
                            ? submit.error.message
                            : 'Unable to submit this section.'}
                    </p>
                )}
                {submit.isSuccess && (
                    <p role="status" className="mt-3 text-sm">
                        Section received. Reference: {submit.data.submissionId}
                    </p>
                )}
            </CardContent>
        </Card>
    );
}
